  const remaining = new Map(active.map((s) => [s.id, s]));
  const actors: Actor[] = [];
  const occupied = new Set<number>();
  const add = (s: RecentSession, seat: Actor['seat']) => {
    actors.push({
      id: s.id,
      label: s.label,
      workspaceTitle: s.workspaceTitle,
      status: s.status,
      activity: s.activity,
      seat,
      roaming: true,
    });
    occupied.add(seat);
    remaining.delete(s.id);
  };
