"@deepseek-ai/dsh-client-ui-workspace\": \"0.2.1-rc.2\",\n    \"@gltf-transform/core\": \"4.5.1\",\n    \"@gltf-transform/extensions\": \"4.5.1\",\n    \"@gltf-transform/functions\": \"4.5.1\",\n    \"@types/node\": \"^22.15.3\",\n    \"@types/react\": \"~18.3.1\",\n    \"@types/react-dom\": \"^18.3.1\",\n    \"@types/three\": \"^0.180.0\",\n    \"gltf-validator\": \"2.0.0-dev.3.10\",\n    \"meshoptimizer\": \"1.3.0\",\n    \"sharp\": \"0.35.5\",\n    \"react\": \"^18.2.0\",\n    \"react-dom\": \"^18.2.0\",\n    \"tsdown\": \"0.22.2\",\n    \"typescript\": \"^5.9.3\"\n  }\n}\n"
