    {
      "path": "packages/clutch-dsh-office/src/client/entry.tsx",
      "content": "import type { Context } from '@deepseek-ai/cordis';\nimport type { ConnectionHandle } from '@deepseek-ai/dsh-client-connection/client';\nimport type { PropsRuntime, PropsLocale } from '@deepseek-ai/dsh-client-ui-slots';\nimport type {} from '@deepseek-ai/dsh-client-ui-renderer/client';\nimport type {} from '@deepseek-ai/dsh-client-ui-sidebar/client';\nimport type {} from '@deepseek-ai/dsh-client-ui-layout/client';\nimport type {} from '@deepseek-ai/dsh-client-ui-session/client';\nimport type {\n  SessionStatusSnapshot,\n  UseSessionStatus,\n  UseSessions,\n} from '@deepseek-ai/dsh-client-ui-session/client';\nimport type { SessionListState } from '@deepseek-ai/dsh-api-session-controller/client';\nimport type {} from '@deepseek-ai/dsh-client-locale/client';\nimport type {} from '@deepseek-ai/dsh-api-workspace-controller/client';\nimport type {} from '@deepseek-ai/dsh-client-ui-workspace/client';\nimport { useLayoutEffect, useMemo, useRef, useSyncExternalStore } from 'react';\nimport { projectSessionBoard } from '../office/session-board.js';\nimport type { Actor } from '../office/types.js';\nimport { recentSessionFacts } from './native-facts.js';\nimport { OfficeDashboard } from './OfficeDashboard.js';\nimport { en, zh } from './locales.js';\nimport { OFFICE_CSS } from './styles.js';\nimport { officePhase } from './readiness.js';\n\ndeclare module '@deepseek-ai/dsh-client-ui-slots' {\n  interface LocaleNamespaceMap {\n    'clutch.office': keyof typeof en;\n  }\n}\n\ndeclare const __OFFICE_VERSION__: string;\n\nexport const inject = ['slots', 'locale', 'workspaces', 'layout', 'connection', 'uiWorkspace'];\n\nfunction subscribeOnline(listener: () => void): () => void {\n  window.addEventListener('online', listener);\n  window.addEventListener('offline', listener);\n  return () => {\n    window.removeEventListener('online', listener);\n    window.removeEventListener('offline', listener);\n  };\n}\nconst isOnline = () => navigator.onLine;\n\nfunction OfficeIcon({ size }: { size: number }) {\n  return (\n    <svg width={size} height={size} viewBox=\"0 0 24 24\" fill=\"none\" aria-hidden=\"true\">\n      <path\n        d=\"M3 11.5 12 4l9 7.5V21H3zM9 21v-7h6v7\"\n        stroke=\"currentColor\"\n        strokeWidth=\"1.6\"\n        strokeLinejoin=\"round\"\n      />\n      <path d=\"M8 8V4M16 8V4\" stroke=\"currentColor\" strokeWidth=\"1.6\" strokeLinecap=\"round\" />\n    </svg>\n  );\n}\n\ntype NativeProps = PropsRuntime<'main'> &\n  PropsLocale<'clutch.office'> & {\n    source: Context['workspaces']['list'];\n    connection: ConnectionHandle;\n    openSession: (id: string) => void;\n  };\n\nfunction NativeOffice({\n  source,\n  connection,\n  useSessions,\n  useSessionStatus,\n  openSession,\n  t,\n}: NativeProps) {\n  const online = useSyncExternalStore(subscribeOnline, isOnline);\n  const state = useSyncExternalStore(connection.state.subscribe, connection.state.getSnapshot);\n  const generation = useSyncExternalStore(\n    connection.generation.subscribe,\n    connection.generation.getSnapshot,\n  );\n  const workspace = useSyncExternalStore(\n    source.subscribe.bind(source),\n    source.getSnapshot.bind(source),\n  );\n  const list: SessionListState = (useSessions as UseSessions)((value: SessionListState) => value);\n  const status: SessionStatusSnapshot = (useSessionStatus as UseSessionStatus)(\n    (value: SessionStatusSnapshot) => value,\n  );\n  const previous = useRef<readonly Actor[]>([]);\n  const board = useMemo(() => {\n    const projections = new Map(Object.entries(list.projectionsBySession));\n    const facts = recentSessionFacts(\n      list.ids,\n      list.byId,\n      status,\n      workspace.archivedSessionIds,\n      workspace.items.map((item) => ({\n        id: item.workspaceId,\n        title: item.title,\n        sessionIds: item.sessionIds,\n      })),\n      (id) => {\n        const title: unknown = Object.entries(projections.get(id)?.values ?? {}).find(\n          ([key]) => key === 'title',\n        )?.[1];\n        return typeof title === 'string' ? title : undefined;\n      },\n      t('ungrouped'),\n    );\n    return projectSessionBoard(facts, previous.current);\n  }, [workspace, list, status, t]);\n  useLayoutEffect(() => {\n    previous.current = board.office.actors;\n  }, [board]);\n  const phase = officePhase({\n    online,\n    connection: state,\n    generation,\n    workspaceState: workspace.state,\n    workspacePhase: workspace.phase,\n    sessionPhase: list.phase,\n  });\n  return (\n    <OfficeDashboard\n      version={__OFFICE_VERSION__}\n      board={board}\n      phase={phase}\n      t={t}\n      onOpenSession={openSession}\n    />\n  );\n}\n\nexport function apply(ctx: Context): void {\n  ctx.effect(() => ctx.locale.register('clutch.office', { en, zh }));\n  ctx.effect(() => {\n    const style = document.createElement('style');\n    style.dataset.clutchOffice = '';\n    style.textContent = OFFICE_CSS;\n    document.head.append(style);\n    return () => style.remove();\n  });\n  ctx.slots.inject('main', () =>\n    ctx.slots.register(\n      {\n        name: 'main',\n        key: 'clutch-dsh-office',\n        locale: 'clutch.office',\n        inject: () => ({\n          source: ctx.workspaces.list,\n          connection: ctx.get('connection') as ConnectionHandle,\n          openSession: (id: string) =>\n            ctx.uiWorkspace.openSession(id as Parameters<Context['uiWorkspace']['openSession']>[0]),\n        }),\n      },\n      NativeOffice,\n    ),\n  );\n  ctx.slots.inject('sidebar.panellist', () =>\n    ctx.slots.register(\n      {\n        name: 'sidebar.panellist',\n        id: 'clutch-dsh-office',\n        order: 45,\n        label: () => ctx.locale.bind('clutch.office')('nav'),\n      },\n      OfficeIcon,\n    ),\n  );\n}\n"
    },
    {
      "path": "packages/clutch-dsh-office/src/client/OfficeDashboard.tsx",
      "content": "import { useEffect, useMemo, useRef, useState } from 'react';\nimport { activityClocks, elapsedTime, type ActivityClock } from './session-time.js';\nimport type { RecentSession, SessionBoard } from '../office/types.js';\nimport { projectSessionBoard } from '../office/session-board.js';\nimport type { Copy } from './locales.js';\nimport { KitchenCanvas } from './scene/KitchenCanvas.js';\n\nexport interface DashboardProps {\n  readonly board: SessionBoard;\n  readonly version: string;\n  readonly phase: 'loading' | 'ready' | 'error';\n  readonly t: Copy;\n  readonly onOpenSession: (id: string) => void;\n}\n\nexport function OfficeDashboard({ board, phase, t, onOpenSession, version }: DashboardProps) {\n  const [preview, setPreview] = useState(false);\n  const [count, setCount] = useState(4);\n  const [previewEpoch] = useState(Date.now);\n  const demo: RecentSession[] = useMemo(\n    () =>\n      Array.from({ length: count }, (_, i) => ({\n        id: `preview-${i}`,\n        label: [t('sampleBuild'), t('sampleReview'), t('sampleDone'), t('samplePlan')][i],\n        workspaceTitle: ['clutch-dsh', 'whale-studio', 'kitchen', 'clutch-dsh'][i],\n        eligible: true,\n        activity: i === 1 || i === 3 ? 'waiting' : i === 2 ? 'idle' : 'working',\n        status: (['running', 'question', 'unread', 'approval'] as const)[i],\n        running: i === 0,\n        unread: i === 2,\n        updatedAt: previewEpoch - (i === 0 ? 20_000 : 65_000),\n      })),\n    [count, t, previewEpoch],\n  );\n  const display = useMemo(\n    () => (preview ? projectSessionBoard(demo) : board),\n    [preview, demo, board],\n  );\n  const ready = preview || phase === 'ready';\n  const office = ready\n    ? display.office\n    : { ...display.office, actors: [], activeCount: 0, overflow: 0 };\n  const rows = useMemo(() => (ready ? display.sessions : []), [ready, display.sessions]);\n  const previousClocks = useRef<ReadonlyMap<string, ActivityClock>>(new Map());\n  const [now, setNow] = useState(Date.now);\n  const clocks = useMemo(() => activityClocks(previousClocks.current, rows, Date.now()), [rows]);\n  useEffect(() => {\n    previousClocks.current = clocks;\n    setNow(Date.now());\n  }, [clocks]);\n  const hasRunning = rows.some((row) => row.status === 'running');\n  useEffect(() => {\n    if (!hasRunning) return;\n    let timer: ReturnType<typeof setInterval> | undefined;\n    const sync = () => {\n      if (timer !== undefined) clearInterval(timer);\n      timer = undefined;\n      if (!document.hidden) {\n        setNow(Date.now());\n        timer = setInterval(() => setNow(Date.now()), 1000);\n      }\n    };\n    sync();\n    document.addEventListener('visibilitychange', sync);\n    return () => {\n      if (timer !== undefined) clearInterval(timer);\n      document.removeEventListener('visibilitychange', sync);\n    };\n  }, [hasRunning]);\n  return (\n    <section className=\"co-office\" aria-label={t('nav')}>\n      <header className=\"co-header\">\n        <div>\n          <div className=\"co-eyebrow\">\n            DSH Office{' '}\n            <span\n              className=\"co-version\"\n              title={t('previewVersionHint')}\n              onDoubleClick={() => setPreview((value) => !value)}\n            >\n              v{version}\n            </span>\n          </div>\n          <h1>{t('boardTitle')}</h1>\n        </div>\n        <div className=\"co-header-right\">\n          <span className=\"co-count\" role=\"status\">\n            {ready ? `${office.activeCount} ${t('attentionSessions')}` : t('loading')}\n          </span>\n        </div>\n      </header>\n      {preview && (\n        <div className=\"co-preview-controls\">\n          <strong>{t('previewLabel')}</strong>\n          {[1, 2, 3, 4].map((n) => (\n            <button\n              key={n}\n              className=\"co-chip\"\n              aria-pressed={count === n}\n              onClick={() => setCount(n)}\n            >\n              {n} {t('actors')}\n            </button>\n          ))}\n          <small>{t('previewNote')}</small>\n        </div>\n      )}\n      <article className=\"co-room\">\n        <KitchenCanvas office={office} t={t} onOpenSession={preview ? undefined : onOpenSession} />\n        {!ready && (\n          <div className=\"co-scene-caption\" role=\"status\">\n            {t(phase === 'error' ? 'unavailable' : 'loading')}\n          </div>\n        )}\n      </article>\n      <section className=\"co-recent\" aria-label={t('recentSessions')}>\n        <header>\n          <h2>{t('recentSessions')}</h2>\n          <span className=\"co-count\">{ready ? rows.length : '—'}</span>\n        </header>\n        {!ready ? (\n          <p role=\"status\">{t(phase === 'error' ? 'unavailable' : 'loading')}</p>\n        ) : rows.length === 0 ? (\n          <p className=\"co-vacant\">{t('noRecent')}</p>\n        ) : (\n          <ul className=\"co-session-list\">\n            {rows.map((row) => (\n              <li key={row.id}>\n                <button\n                  className=\"co-session-row\"\n                  disabled={preview}\n                  onClick={() => onOpenSession(row.id)}\n                  data-office-session={row.id}\n                >\n                  <span className=\"co-session-identity\">\n                    <strong>{row.label}</strong>\n                    <span>{row.workspaceTitle}</span>\n                  </span>\n                  <span className=\"co-session-meta\">\n                    {row.status === 'running' ? (\n                      <>\n                        <span\n                          className=\"co-running-icon\"\n                          role=\"img\"\n                          aria-label={t('running')}\n                          title={t('running')}\n                        />\n                        <time\n                          title={\n                            clocks.get(row.id)?.since === undefined\n                              ? undefined\n                              : new Date(clocks.get(row.id)!.since!).toLocaleString()\n                          }\n                        >\n                          {elapsedTime(clocks.get(row.id)?.since, now) === undefined\n                            ? t('timeUnknown')\n                            : `${t('runningFor')} ${elapsedTime(clocks.get(row.id)?.since, now)}`}\n                        </time>\n                      </>\n                    ) : row.status === 'unread' ? (\n                      <>\n                        <span\n                          className=\"co-done-icon\"\n                          role=\"img\"\n                          aria-label={t('unread')}\n                          title={t('unread')}\n                        >\n                          ✓\n                        </span>\n                        <time\n                          dateTime={\n                            clocks.get(row.id)?.since === undefined\n                              ? undefined\n                              : new Date(clocks.get(row.id)!.since!).toISOString()\n                          }\n                          title={\n                            clocks.get(row.id)?.since === undefined\n                              ? undefined\n                              : new Date(clocks.get(row.id)!.since!).toLocaleString()\n                          }\n                        >\n                          {clocks.get(row.id)?.since === undefined\n                            ? t('timeUnknown')\n                            : `${t('completedAt')} ${new Date(clocks.get(row.id)!.since!).toLocaleTimeString()}`}\n                        </time>\n                      </>\n                    ) : (\n                      <span className=\"co-state\" data-state={row.status}>\n                        {t(row.status === 'idle' ? 'sessionIdle' : row.status)}\n                      </span>\n                    )}\n                  </span>\n                </button>\n              </li>\n            ))}\n          </ul>\n        )}\n      </section>\n    </section>\n  );\n}\n"
    },
    {
      "path": "packages/clutch-dsh-office/src/client/readiness.ts",
      "content": "export type OfficePhase = 'loading' | 'ready' | 'error';\n\n/** A cached domain baseline alone cannot establish current connectivity. */\nexport function officePhase(input: {\n  readonly online: boolean;\n  readonly connection: string | undefined;\n  readonly generation: object | undefined;\n  readonly workspaceState: 'idle' | 'loading' | 'error';\n  readonly workspacePhase: 'pending' | 'ready';\n  readonly sessionPhase: 'pending' | 'ready';\n}): OfficePhase {\n  if (!input.online || input.connection !== 'connected' || input.generation === undefined)\n    return 'loading';\n  if (input.workspaceState === 'error') return 'error';\n  if (\n    input.workspaceState === 'loading' ||\n    input.workspacePhase !== 'ready' ||\n    input.sessionPhase !== 'ready'\n  )\n    return 'loading';\n  return 'ready';\n}\n"
    },
    {
      "path": "packages/clutch-dsh-office/src/client/native-facts.ts",
      "content": "import type { RecentSession, SessionFact, SessionState, WorkspaceFact } from '../office/types.js';\n\ninterface NativeSummary {\n  readonly blank: boolean;\n  readonly origin?: string;\n  readonly running: boolean;\n  readonly title?: string;\n  readonly displayTitle?: string;\n  readonly updatedAt?: number;\n  readonly cwd?: string;\n  readonly parentId?: string;\n}\ninterface NativeStatus {\n  readonly running: boolean | undefined;\n  readonly pendingInteraction: unknown;\n  readonly completionUnread?: boolean;\n}\n\n/** Read-only normalization; deliberately accepts native identities as strings across peer graphs. */\nexport function sessionFacts(\n  ids: readonly string[],\n  byId: Readonly<Record<string, NativeSummary>>,\n  statuses: Iterable<readonly [string, NativeStatus]>,\n  archivedIds: readonly string[],\n  titleFor: (id: string) => string | undefined,\n): Map<string, SessionFact> {\n  const status = new Map(statuses);\n  const archived = new Set(archivedIds);\n  return new Map(\n    ids.flatMap((id) => {\n      const summary = byId[id];\n      if (!summary) return [];\n      const current = status.get(id);\n      const fact: SessionFact = {\n        id,\n        label: summary.title || titleFor(id) || summary.displayTitle || id.slice(0, 8),\n        eligible: !archived.has(id) && !summary.blank && summary.origin !== 'subagent',\n        activity: current?.pendingInteraction\n          ? 'waiting'\n          : (current?.running ?? summary.running)\n            ? 'working'\n            : 'idle',\n      };\n      return [[id, fact] as const];\n    }),\n  );\n}\n\n/** Only Host-list members, never catalog-only rows; no retain, history reads or unread writes. */\nexport function recentSessionFacts(\n  ids: readonly string[],\n  byId: Readonly<Record<string, NativeSummary>>,\n  statuses: Iterable<readonly [string, NativeStatus]>,\n  archivedIds: readonly string[],\n  workspaces: readonly WorkspaceFact[],\n  titleFor: (id: string) => string | undefined,\n  ungrouped: string,\n): RecentSession[] {\n  const status = new Map(statuses),\n    archived = new Set(archivedIds);\n  const listed = new Set(ids);\n  const runningChildren = new Set<string>();\n  for (const id of listed) {\n    let child = byId[id];\n    if (child?.origin !== 'subagent' || !(status.get(id)?.running ?? child.running)) continue;\n    const seen = new Set<string>([id]);\n    while (child?.origin === 'subagent' && child.parentId && !seen.has(child.parentId)) {\n      seen.add(child.parentId);\n      runningChildren.add(child.parentId);\n      child = byId[child.parentId];\n    }\n  }\n  return [...listed].flatMap((id) => {\n    const summary = byId[id];\n    if (!summary || archived.has(id) || summary.blank || summary.origin === 'subagent') return [];\n    const current = status.get(id),\n      interaction = current?.pendingInteraction;\n    const kind =\n      interaction && typeof interaction === 'object' && 'kind' in interaction\n        ? interaction.kind\n        : undefined;\n    const pending =\n      kind === 'approval' || kind === 'plan-review' || kind === 'question' ? kind : undefined;\n    const running = (current?.running ?? summary.running) || runningChildren.has(id);\n    const unread = current?.completionUnread === true;\n    const state: SessionState = pending ?? (running ? 'running' : unread ? 'unread' : 'idle');\n    const workspace = workspaces.find((w) => w.sessionIds.includes(id));\n    return [\n      {\n        id,\n        label: summary.title || titleFor(id) || summary.displayTitle || id.slice(0, 8),\n        eligible: true,\n        workspaceId: workspace?.id,\n        workspaceTitle: workspace?.title || ungrouped,\n        status: state,\n        running,\n        unread,\n        activity: pending ? 'waiting' : running ? 'working' : 'idle',\n        updatedAt: Number.isFinite(summary.updatedAt) ? summary.updatedAt : undefined,\n        cwd: summary.cwd,\n        parentId: summary.parentId,\n      },\n    ];\n  });\n}\n"
    },
    {
      "path": "packages/clutch-dsh-office/src/office/session-board.ts",
      "content": "import type { Actor, RecentSession, SessionBoard } from './types.js';\n\n/** Session identity owns a stable visual slot; native state owns unread acknowledgement. */\nexport function projectSessionBoard(\n  sessions: readonly RecentSession[],\n  previous: readonly Actor[] = [],\n): SessionBoard {\n  const recent = [\n    ...new Map(sessions.filter((s) => s.eligible).map((s) => [s.id, s])).values(),\n  ].sort((a, b) => (b.updatedAt ?? 0) - (a.updatedAt ?? 0) || a.id.localeCompare(b.id));\n  const active = recent.filter((s) => s.status !== 'idle');\n  const remaining = new Map(active.map((s) => [s.id, s]));\n  const actors: Actor[] = [];\n  const occupied = new Set<number>();\n  const add = (s: RecentSession, seat: Actor['seat']) => {\n    actors.push({\n      id: s.id,\n      label: s.label,\n      workspaceTitle: s.workspaceTitle,\n      status: s.status,\n      activity: s.activity,\n      seat,\n      roaming: true,\n    });\n    occupied.add(seat);\n    remaining.delete(s.id);\n  };\n  for (const actor of previous) {\n    const s = remaining.get(actor.id);\n    if (s && actors.length < 4 && !occupied.has(actor.seat)) add(s, actor.seat);\n  }\n  for (const s of remaining.values()) {\n    if (actors.length === 4) break;\n    const seat = ([0, 1, 2, 3] as const).find((n) => !occupied.has(n))!;\n    add(s, seat);\n  }\n  return {\n    sessions: active,\n    office: {\n      id: 'session-office',\n      title: 'Office',\n      actors,\n      activeCount: active.length,\n      overflow: active.length - actors.length,\n    },\n  };\n}\n"
    },
    {
      "path": "packages/clutch-dsh-office/src/client/session-time.ts",
      "content": "import type { RecentSession } from '../office/types.js';\n\nexport interface ActivityClock {\n  readonly running: boolean;\n  readonly updatedAt: number | undefined;\n  readonly since: number | undefined;\n}\n\n/** Mirrors notification-bell display clocks, never persisted or treated as native events. */\nexport function activityClocks(\n  previous: ReadonlyMap<string, ActivityClock>,\n  sessions: readonly RecentSession[],\n  now: number,\n): ReadonlyMap<string, ActivityClock> {\n  return new Map(\n    sessions.map((session) => {\n      const old = previous.get(session.id);\n      const updatedAt = Number.isFinite(session.updatedAt) ? session.updatedAt : undefined;\n      const transitioned = old !== undefined && old.running !== session.running;\n      const newPrompt =\n        session.running &&\n        updatedAt !== undefined &&\n        (old?.updatedAt === undefined || updatedAt > old.updatedAt);\n      return [\n        session.id,\n        {\n          running: session.running,\n          updatedAt,\n          since: transitioned ? now : newPrompt ? updatedAt : (old?.since ?? updatedAt),\n        },\n      ];\n    }),\n  );\n}\n\nexport function elapsedTime(since: number | undefined, now: number): string | undefined {\n  if (since === undefined || !Number.isFinite(since) || !Number.isFinite(now)) return undefined;\n  const seconds = Math.max(0, Math.floor((now - since) / 1000));\n  if (seconds < 60) return `${seconds}s`;\n  const minutes = Math.floor(seconds / 60);\n  if (minutes < 60) return `${minutes}m ${seconds % 60}s`;\n  return `${Math.floor(minutes / 60)}h ${minutes % 60}m`;\n}\n"
    },
    {
      "path": "packages/clutch-dsh-office/src/client/scene/KitchenCanvas.tsx",
      "content": "import { useEffect, useRef, useState } from 'react';\nimport type { Actor, Office } from '../../office/types.js';\nimport type { Copy } from '../locales.js';\nimport { createKitchenRuntime, type SceneRuntime } from './runtime.js';\n\nfunction Bubble({\n  actor,\n  t,\n  onOpenSession,\n}: {\n  actor: Actor;\n  t: Copy;\n  onOpenSession?: (id: string) => void;\n}) {\n  const state =\n    actor.status ??\n    (actor.activity === 'waiting' ? 'question' : actor.activity === 'working' ? 'running' : 'idle');\n  return (\n    <button\n      type=\"button\"\n      data-seat={actor.seat}\n      data-state={state}\n      className=\"co-bubble\"\n      disabled={!onOpenSession}\n      onClick={() => onOpenSession?.(actor.id)}\n      title={`${actor.label} · ${actor.workspaceTitle ?? ''} · ${t(state === 'idle' ? 'sessionIdle' : state)}`}\n    >\n      <span className=\"co-bubble-identity\">\n        <strong>{actor.label}</strong>\n        <small>{actor.workspaceTitle}</small>\n      </span>\n      <span className=\"co-state\" data-state={state}>\n        {t(state === 'idle' ? 'sessionIdle' : state)}\n      </span>\n    </button>\n  );\n}\n\nexport function KitchenCanvas({\n  office,\n  t,\n  onOpenSession,\n}: {\n  office: Office;\n  t: Copy;\n  onOpenSession?: (id: string) => void;\n}) {\n  const container = useRef<HTMLDivElement>(null);\n  const runtime = useRef<SceneRuntime>();\n  const latestActors = useRef(office.actors);\n  latestActors.current = office.actors;\n  const [failure, setFailure] = useState<'webgl' | 'contextLost'>();\n  const [attempt, setAttempt] = useState(0);\n  useEffect(() => {\n    const element = container.current;\n    if (!element) return;\n    let failed = false;\n    const observer = new IntersectionObserver(([entry]) => {\n      // Offscreen rooms release their contexts, so a long overview cannot exhaust WebGL's context limit.\n      if (!entry.isIntersecting) {\n        runtime.current?.dispose();\n        runtime.current = undefined;\n        return;\n      }\n      if (failed || runtime.current) return;\n      try {\n        runtime.current = createKitchenRuntime(element, (kind) => {\n          failed = true;\n          setFailure(kind);\n        });\n        runtime.current.update(latestActors.current);\n      } catch (error) {\n        console.warn('clutch-dsh-office: WebGL initialization failed', error);\n        failed = true;\n        setFailure('webgl');\n      }\n    });\n    observer.observe(element);\n    return () => {\n      observer.disconnect();\n      runtime.current?.dispose();\n      runtime.current = undefined;\n    };\n  }, [attempt]);\n  useEffect(() => {\n    runtime.current?.update(office.actors);\n  }, [office.actors]);\n  return (\n    <div className=\"co-canvas\" ref={container} aria-label={office.title}>\n      {office.actors.map((actor) => (\n        <Bubble key={actor.id} actor={actor} t={t} onOpenSession={onOpenSession} />\n      ))}\n      {failure && (\n        <div className=\"co-scene-error\" role=\"alert\">\n          {t(failure)}\n          <button\n            className=\"co-button\"\n            onClick={() => {\n              setFailure(undefined);\n              setAttempt((value) => value + 1);\n            }}\n          >\n            {t('retry')}\n          </button>\n        </div>\n      )}\n    </div>\n  );\n}\n"
    },
    {
      "path": "packages/clutch-dsh-office/src/client/scene/runtime.ts",
      "content": "import * as T from 'three';\nimport './baked-assets.js';\nimport { kitchenActorGroundY } from '../../office/kitchen-layout.js';\nimport { planAction } from '../../office/actions.js';\nimport {\n  createKitchenMotion,\n  advanceKitchenMotion,\n  type KitchenMotion,\n} from '../../office/kitchen-motion.js';\nimport {\n  ROAM_SCALE,\n  createRoamingMotion,\n  advanceRoamingMotion,\n  type RoamingMotion,\n} from '../../office/roaming.js';\nimport type { Actor } from '../../office/types.js';\nimport { Models, type CharacterAppearance } from './models.js';\nimport { buildKitchen } from './kitchen/index.js';\nimport { createKitchenCamera, resizeKitchenCamera } from './camera.js';\nimport { buildDeepSeek } from './character/deepseek.js';\nimport { turnVelocity } from './character/turn.js';\nimport { createKitchenLighting } from './lighting.js';\nimport { createKitchenRenderGuard } from './render-failure.js';\nimport { kitchenPixelRatio } from './render-budget.js';\nimport { createKitchenStaticFrame } from './static-frame.js';\n\nexport interface SceneRuntime {\n  update(actors: readonly Actor[]): void;\n  setVisible(visible: boolean): void;\n  dispose(): void;\n}\n\ninterface LiveActor {\n  motion: KitchenMotion;\n  roaming?: RoamingMotion;\n  model: CharacterAppearance;\n  actor: Actor;\n  models: Models;\n  bubble: HTMLElement;\n}\n\n/** Owns one WebGL context; consumes presentation facts without touching DSH. */\nexport function createKitchenRuntime(\n  container: HTMLElement,\n  onFailure: (kind: 'webgl' | 'contextLost') => void,\n): SceneRuntime {\n  const renderer = new T.WebGLRenderer({ antialias: true, alpha: true });\n  renderer.setPixelRatio(\n    kitchenPixelRatio(container.clientWidth, container.clientHeight, window.devicePixelRatio),\n  );\n  renderer.domElement.setAttribute('aria-hidden', 'true');\n  const scene = new T.Scene();\n  let lighting: ReturnType<typeof createKitchenLighting>;\n  try {\n    lighting = createKitchenLighting(scene, renderer);\n  } catch (error) {\n    renderer.dispose();\n    renderer.forceContextLoss();\n    throw error;\n  }\n  const camera = createKitchenCamera();\n  const models = new Models(() => schedule(true));\n  scene.add(buildKitchen(models));\n  const actors = new Map<string, LiveActor>();\n  let width = 1;\n  let height = 1;\n  let visible = true;\n  let disposed = false;\n  let failed = false;\n  let frame = 0;\n  const frameInterval = 1000 / 30;\n  let last: number | undefined;\n  let nextDrawAt: number | undefined;\n  let elapsed = 0;\n  const reduced = window.matchMedia('(prefers-reduced-motion: reduce)');\n  const clock = new T.Vector3();\n  const staticFrame = createKitchenStaticFrame(renderer, scene, camera, () => {\n    lighting.updateCharacterShadows(camera);\n  });\n  const renderGuard = createKitchenRenderGuard(\n    {\n      debug: renderer.debug,\n      render() {\n        staticFrame.render();\n      },\n    },\n    () => {\n      failed = true;\n      cancelAnimationFrame(frame);\n      frame = 0;\n      onFailure('webgl');\n    },\n  );\n\n  const draw = (now: number) => {\n    frame = 0;\n    if (disposed || failed || !visible || document.hidden) return;\n    // Keep the timestamp of the last *drawn* frame: skipped RAFs must not slow motion.\n    if (actors.size && !reduced.matches && nextDrawAt !== undefined && now < nextDrawAt - 1e-6) {\n      frame = requestAnimationFrame(draw);\n      return;\n    }\n    const delta = last === undefined ? 0 : Math.min((now - last) / 1000, 0.06);\n    last = now;\n    // Keep a cadence deadline rather than resetting it to the last RAF. Small\n    // refresh-rate drift otherwise forces a whole extra RAF skip every frame.\n    nextDrawAt =\n      nextDrawAt === undefined\n        ? now + frameInterval\n        : nextDrawAt +\n          Math.max(1, Math.floor((now - nextDrawAt) / frameInterval) + 1) * frameInterval;\n    elapsed += delta;\n    for (const live of actors.values()) {\n      const { model, actor } = live;\n      const plan = planAction(actor.activity, (actor.seat % 2) as 0 | 1);\n      const previousPosition = live.roaming?.position ?? live.motion.position;\n      const previousYaw = live.roaming?.yaw ?? live.motion.yaw;\n      if (actor.roaming) {\n        live.roaming = advanceRoamingMotion(\n          live.roaming ?? createRoamingMotion(actor.seat),\n          [...actors.values()]\n            .filter((p) => p !== live)\n            .flatMap((p) => (p.roaming ? [p.roaming] : [])),\n          delta,\n          reduced.matches,\n          model.animation?.walkSpeed ?? 0.48,\n        );\n      } else {\n        live.motion = advanceKitchenMotion(\n          live.motion,\n          plan,\n          delta,\n          reduced.matches,\n          model.animation?.walkSpeed,\n        );\n      }\n      const { position, yaw, moving } = live.roaming ?? live.motion;\n      model.root.position.set(\n        position[0],\n        kitchenActorGroundY(\n          position,\n          actor.roaming ? 0.054 : model.animation ? 0.025 : 0.04,\n          model.animation ? 0 : 0.012,\n        ),\n        position[1],\n      );\n      model.root.rotation.y = yaw;\n      const motion = reduced.matches ? 0 : Math.sin(elapsed * (moving ? 10 : 3));\n      if (model.animation) {\n        const speed =\n          delta > 0\n            ? Math.hypot(position[0] - previousPosition[0], position[1] - previousPosition[1]) /\n              delta\n            : 0;\n        model.animation.update(\n          delta,\n          !actor.roaming && live.motion.phase === 'retreat' ? -speed : speed,\n          reduced.matches,\n          !actor.roaming &&\n            plan.pose === 'search' &&\n            live.motion.phase === 'idle' &&\n            !live.motion.returning,\n          turnVelocity(previousYaw, yaw, delta),\n        );\n      } else {\n        const baseY =\n          (model.body.userData.officeBaseY as number | undefined) ?? model.body.position.y;\n        model.body.userData.officeBaseY = baseY;\n        model.body.position.y = baseY + (moving ? Math.abs(motion) * 0.045 : motion * 0.012);\n        if (model.arm) {\n          model.arm.rotation.x = moving\n            ? motion * 0.4\n            : plan.pose === 'cook'\n              ? 1.1 + motion * 0.25\n              : plan.pose === 'search'\n                ? -1.1\n                : 0;\n          model.arm.rotation.z = plan.pose === 'wait' ? -1.3 : 0.15;\n        }\n        if (model.tail) model.tail.rotation.z = motion * 0.08;\n      }\n      clock\n        .set(position[0], actor.roaming ? 1.62 * ROAM_SCALE + 0.025 : 1.62, position[1])\n        .project(camera);\n      live.bubble.style.left = `${((clock.x + 1) * width) / 2}px`;\n      live.bubble.style.top = `${((1 - clock.y) * height) / 2}px`;\n    }\n    const labels = [...actors.values()].map((live) => live.bubble);\n    for (let i = 0; i < labels.length; i++) {\n      const bubble = labels[i];\n      const sourceTop = Number.parseFloat(bubble.style.top);\n      let top = sourceTop;\n      const left = Number.parseFloat(bubble.style.left);\n      for (let j = 0; j < i; j++) {\n        const other = labels[j];\n        if (\n          Math.abs(left - Number.parseFloat(other.style.left)) < 195 &&\n          Math.abs(top - Number.parseFloat(other.style.top)) < 56\n        )\n          top = Number.parseFloat(other.style.top) - 59;\n      }\n      top = Math.max(70, top);\n      bubble.style.top = `${top}px`;\n      bubble.style.setProperty?.('--co-leader-height', `${Math.max(12, sourceTop - top + 12)}px`);\n      bubble.style.left = `${Math.max(Math.min(125, width / 2), Math.min(width - Math.min(125, width / 2), left))}px`;\n    }\n    if (!renderGuard.render(scene, camera)) return;\n    if (actors.size && !reduced.matches) frame = requestAnimationFrame(draw);\n    else {\n      last = undefined;\n      nextDrawAt = undefined;\n    }\n  };\n  const schedule = (staticShadows = false) => {\n    // Only room asset arrivals alter static occluders; actors have their own map.\n    if (staticShadows) {\n      renderer.shadowMap.needsUpdate = true;\n      staticFrame.invalidate();\n    }\n    if (!frame && !disposed && !failed && visible && !document.hidden)\n      frame = requestAnimationFrame(draw);\n  };\n  const pause = () => {\n    cancelAnimationFrame(frame);\n    frame = 0;\n    last = undefined;\n    nextDrawAt = undefined;\n    for (const live of actors.values()) live.model.animation?.pause();\n  };\n  const visibility = () => {\n    pause();\n    schedule();\n  };\n  const contextLost = (event: Event) => {\n    event.preventDefault();\n    failed = true;\n    pause();\n    onFailure('contextLost');\n  };\n  const resize = new ResizeObserver(() => {\n    width = Math.max(1, container.clientWidth);\n    height = Math.max(1, container.clientHeight);\n    const aspect = width / height;\n    resizeKitchenCamera(camera, aspect);\n    renderer.setPixelRatio(kitchenPixelRatio(width, height, window.devicePixelRatio));\n    renderer.setSize(width, height, false);\n    staticFrame.invalidate();\n    schedule();\n  });\n  container.prepend(renderer.domElement);\n  resize.observe(container);\n  document.addEventListener('visibilitychange', visibility);\n  reduced.addEventListener('change', visibility);\n  renderer.domElement.addEventListener('webglcontextlost', contextLost);\n  schedule();\n\n  return {\n    update(input) {\n      const next = [...new Map(input.map((actor) => [actor.id, actor])).values()].slice(0, 4);\n      const keep = new Set(next.map((actor) => actor.id));\n      for (const [id, live] of actors) {\n        if (keep.has(id)) continue;\n        scene.remove(live.model.root);\n        live.models.dispose();\n        actors.delete(id);\n      }\n      for (const actor of next) {\n        const current = actors.get(actor.id);\n        if (current) {\n          current.actor = actor;\n          continue;\n        }\n        const actorModels = new Models(() => schedule(), true);\n        const model = buildDeepSeek(actorModels, actor.seat, models);\n        if (actor.roaming) model.root.scale.setScalar(ROAM_SCALE);\n        const bubble = container.querySelector<HTMLElement>(`[data-seat=\"${actor.seat}\"]`);\n        if (!bubble) {\n          actorModels.dispose();\n          continue;\n        }\n        const motion = createKitchenMotion((actor.seat % 2) as 0 | 1);\n        const roaming = actor.roaming ? createRoamingMotion(actor.seat) : undefined;\n        model.root.position.set(motion.position[0], 0.04, motion.position[1]);\n        model.root.rotation.y = motion.yaw;\n        scene.add(model.root);\n        actors.set(actor.id, { model, actor, models: actorModels, bubble, motion, roaming });\n      }\n      schedule();\n    },\n    setVisible(value) {\n      visible = value;\n      pause();\n      schedule();\n    },\n    dispose() {\n      disposed = true;\n      pause();\n      resize.disconnect();\n      document.removeEventListener('visibilitychange', visibility);\n      reduced.removeEventListener('change', visibility);\n      renderer.domElement.removeEventListener('webglcontextlost', contextLost);\n      for (const actor of actors.values()) actor.models.dispose();\n      actors.clear();\n      models.dispose();\n      renderGuard.dispose();\n      staticFrame.dispose();\n      lighting.dispose();\n      renderer.dispose();\n      renderer.forceContextLoss();\n      renderer.domElement.remove();\n    },\n  };\n}\n"
